function fail(message){$('#error').hidden=false;text('#error',message);text('#status','Choose another recording or try again.');}
function ready(){ $('#analyze').disabled=!model||!wave||!guess||!played||busy;if(wave&&!busy)text('#status',!played?'Play the recording before revealing.':!guess?'Choose Human, Synthetic, or Not sure.':'Ready. Reveal when the audience has made its call.');}
function reset(){voiceRecorder.cancel();epoch++;worker?.terminate();worker=null;busy=false;wave=null;inputMeta=null;lastReport=null;guess=null;played=false;$('#result').hidden=true;$('#empty-result').hidden=false;$('#error').hidden=true;player.pause();player.removeAttribute('src');player.load();if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null;}document.querySelectorAll('[data-guess]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});text('#duration','—');text('#status','Loading audio…');$('#analyze').disabled=true;drawWave(null);drawFrequencyMap(null);}
