async function decode(buffer,info){if(info.type==='wav'){const mono=readPCM(buffer,info);if(info.rate===16000)return mono;const ctx=new OfflineAudioContext(1,Math.ceil(mono.length*16000/info.rate),16000),b=ctx.createBuffer(1,mono.length,info.rate);b.copyToChannel(mono,0);const src=ctx.createBufferSource();src.buffer=b;src.connect(ctx.destination);src.start();return (await ctx.startRendering()).getChannelData(0).slice();}const ctx=new AudioContext({sampleRate:16000});try{const b=await ctx.decodeAudioData(buffer.slice(0));if(b.duration>60.05||b.duration<2)throw Error('Choose 2–60 seconds of audio.');const out=new Float32Array(b.length);for(let ch=0;ch<b.numberOfChannels;ch++){const a=b.getChannelData(ch);for(let i=0;i<out.length;i++)out[i]+=a[i]/b.numberOfChannels;}return out;}finally{await ctx.close();}}
async function loadAudio(blob,name,clip=null){reset();activeClip=clip;const token=epoch;text('#clip-name',name);try{if(blob.size>20*1024*1024)throw Error('Choose a file no larger than 20 MB.');const buffer=await blob.arrayBuffer(),info=inspectFile(buffer),decoded=await decode(buffer,info);if(token!==epoch)return;wave=decoded;inputMeta={format:info.type.toUpperCase(),rate:info.rate??null,channels:info.channels??null,analysisRate:16000,duration:wave.length/16000};objectURL=URL.createObjectURL(blob);player.src=objectURL;text('#duration',(wave.length/16000).toFixed(1)+' s');drawWave(wave);ready();}catch(e){if(token===epoch)fail(e.message||'The browser could not decode this recording. Try a PCM WAV file.');}}
async function chooseClip(id){const clip=reel.find(c=>c.id===id);if(!clip)throw Error('Unknown demo sample.');reset();activeClip=clip;const token=epoch;text('#clip-name','Sample '+String(reel.indexOf(clip)+1).padStart(2,'0'));text('#clip-count',`${reel.indexOf(clip)+1} / ${reel.length}`);try{const r=await fetch(clip.file);if(!r.ok)throw Error('The demo recording could not be loaded. Try again.');const blob=await r.blob();if(token!==epoch)return;await loadAudio(blob,'Sample '+String(reel.indexOf(clip)+1).padStart(2,'0'),clip);}catch(e){if(token===epoch)fail(e.message);}}
