let recordingEpoch=0;
const voiceRecorder=createVoiceRecorder({onState:(state,seconds)=>{const active=state!=='idle';$('#record-start').disabled=active;$('#record-stop').disabled=state!=='recording'||seconds<3;text('#record-status',state==='requesting'?'Allow microphone access in your browser.':state==='recording'?`Recording · ${Math.floor(seconds)} / 15 s`:state==='stopping'?'Finishing recording…':'Microphone off');},onError:message=>fail(message),onComplete:async blob=>{const token=recordingEpoch;text('#status','Preparing your recording…');try{const buffer=await blob.arrayBuffer();if(token!==epoch)return;const captured=await decode(buffer,{type:'recording'});if(token!==epoch)return;await loadAudio(pcmWav(captured),'Your microphone recording');}catch(e){if(token===epoch)fail(e.message||'Could not decode the recording. Try Chrome or upload a WAV file.');}}});
$('#record-start').onclick=()=>{reset();activeClip=null;recordingEpoch=epoch;text('#clip-name','Microphone recording');text('#status','Speak naturally for 3–15 seconds.');void voiceRecorder.start();};
$('#record-stop').onclick=()=>voiceRecorder.stop();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&(voiceRecorder.state==='recording'||voiceRecorder.state==='requesting')){voiceRecorder.cancel();text('#record-status','Recording cancelled because you left this tab.');}});
window.addEventListener('pagehide',()=>voiceRecorder.cancel());
for(const m of ['reel','upload','record'])$('#'+m+'-mode').onclick=()=>setMode(m);
$('#clip-select').onchange=e=>chooseClip(e.target.value);
$('#file-input').onchange=e=>{const file=e.target.files[0];if(file)loadAudio(file,file.name);};
document.querySelectorAll('[data-guess]').forEach(b=>b.onclick=()=>{guess=b.dataset.guess;document.querySelectorAll('[data-guess]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});ready();});
player.addEventListener('timeupdate',()=>{if(player.currentTime>.2&&!played){played=true;ready();}});player.addEventListener('error',()=>{if(player.getAttribute('src'))fail('Playback failed. Try a standard PCM WAV recording.');});
function drawFrequencyMap(x){const cv=$('#frequency-map'),c=cv.getContext('2d'),w=cv.width,h=cv.height;c.clearRect(0,0,w,h);c.fillStyle='#101e33';c.fillRect(0,0,w,h);if(!x)return;const map=frequencyMap(x),left=48,right=12,top=10,bottom=25,pw=w-left-right,ph=h-top-bottom,cw=pw/map.columns,ch=ph/map.bands;for(let col=0;col<map.columns;col++)for(let band=0;band<map.bands;band++){const v=map.values[col][band],hue=190-145*Math.max(0,(v-.25)/.75),light=18+53*v;c.fillStyle=`hsl(${hue} 72% ${light}%)`;c.fillRect(left+col*cw,top+(map.bands-1-band)*ch,Math.ceil(cw)+.2,Math.ceil(ch)+.2);}c.font='12px Segoe UI';c.fillStyle='#b8c7d8';c.fillText('8 kHz',5,top+8);c.fillText('4 kHz',5,top+ph/2+4);c.fillText('20 Hz',5,top+ph);c.fillText('0 s',left,h-6);c.fillText(`${(x.length/16000).toFixed(0)} s`,w-36,h-6);}
function renderFacts(r){const channel=inputMeta?.channels===1?'mono':inputMeta?.channels===2?'stereo':inputMeta?.channels?`${inputMeta.channels} channels`:'unknown channels',input=inputMeta?.rate?`${(inputMeta.rate/1000).toFixed(inputMeta.rate%1000?1:0)} kHz · ${channel}`:'decoder reported';const rms=r.quality.rms>0?(20*Math.log10(r.quality.rms)).toFixed(1)+' dBFS':'—',facts=[['Input',`${inputMeta?.format??'AUDIO'} · ${input}`],['Analysis','16 kHz · mono'],['Duration',`${r.quality.duration.toFixed(1)} s`],['RMS level',rms],['Clipped samples',pct(r.quality.clipping)],['Detector path',Number.isFinite(r.neuralProbability)?'RBF-SVM + AASIST':'RBF-SVM']];$('#signal-facts').replaceChildren(...facts.map(([label,value])=>{const d=document.createElement('div'),s=document.createElement('span'),b=document.createElement('strong');s.textContent=label;b.textContent=value;d.append(s,b);return d;}));}
function drawTimeline(windows){const cv=$('#timeline'),c=cv.getContext('2d'),w=cv.width,h=cv.height;c.clearRect(0,0,w,h);const values=windows.map(x=>x.score),lo=Math.min(-1,...values),hi=Math.max(1,...values),duration=wave.length/16000,X=t=>40+t/duration*(w-60),Y=s=>h-28-(s-lo)/(hi-lo)*(h-48);c.font='13px Segoe UI';c.fillStyle='#56667c';c.strokeStyle='#dce3eb';c.beginPath();c.moveTo(40,Y(0));c.lineTo(w-20,Y(0));c.stroke();c.fillText('0',14,Y(0)+4);c.fillText('Human ← score → Synthetic',40,15);for(let i=0;i<=4;i++){let t=duration*i/4;c.fillText(t.toFixed(0)+'s',X(t)-8,h-5);}c.strokeStyle='#087c7a';c.lineWidth=2.5;c.beginPath();windows.forEach((s,i)=>{const x=X((s.start+s.end)/2),y=Y(s.score);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();windows.forEach(s=>{c.fillStyle=s.score>0?'#ac4b4f':'#007d78';c.beginPath();c.arc(X((s.start+s.end)/2),Y(s.score),3.5,0,Math.PI*2);c.fill();});}
function showResult(raw){const r=applySourcePolicy(raw,mode);$('#result').hidden=false;$('#empty-result').hidden=true;$('#verdict-box').className='verdict '+r.label;text('#verdict',r.policyReason==='neural-safety-challenge'?'Neural challenge — verify':({real:'Likely human',fake:'Likely synthetic',uncertain:'Uncertain — review needed'})[r.label]);text('#verdict-note',r.policyReason==='neural-safety-challenge'?'AASIST did not support the primary human result. Do not treat this recording as verified human.':r.policyReason==='microphone-replay-risk'?'The feature model leaned human, but microphone replay can hide synthetic artifacts. Use the original file when possible.':r.label==='uncertain'?'The evidence does not support a confident call.':r.label==='fake'?'The recording resembles synthetic speech in the training data.':'The recording resembles human speech in the training data.');const dual=Number.isFinite(r.featureProbability)&&Number.isFinite(r.neuralProbability);text('#score-label',dual?'Primary RBF-SVM estimate':'Estimated synthetic probability');text('#score',r.probability<.001?'<0.1%':r.probability>.999?'>99.9%':pct(r.probability));$('#probability').value=r.probability;$('#detector-breakdown').hidden=!dual;if(dual){text('#feature-score',pct(r.featureProbability));text('#neural-score',pct(r.neuralProbability));}text('#warnings',r.warnings.join(' '));$('#truth').hidden=false;if(activeClip){const hit=guess===activeClip.label?'Your guess matches the label.':guess==='unsure'?'You chose not sure.':'Your guess differs from the label.';const modelhit=r.label==='uncertain'?'The model abstained.':r.label===activeClip.label?'The model matches the label.':'The model got this example wrong.';text('#truth',`Source label: ${activeClip.label==='fake'?'Synthetic':'Human'}. ${hit} ${modelhit} Source: ${activeClip.source}. ${activeClip.note||''}`);}else text('#truth','Source label: unknown. This is a model assessment, not an authenticity certificate.');renderFacts(r);drawFrequencyMap(wave);drawTimeline(r.windows);const box=$('#segments');box.replaceChildren();const ranked=[...r.windows].sort((a,b)=>b.score-a.score).filter(x=>x.score>0).slice(0,3);if(!ranked.length){const p=document.createElement('p');p.className='hint';p.textContent='No window crossed the raw synthetic-score boundary. This does not prove the recording is human.';box.append(p);}for(const s of ranked){const b=document.createElement('button');b.textContent=`Listen ${s.start.toFixed(0)}–${s.end.toFixed(0)} s`;b.onclick=()=>{player.currentTime=s.start;player.play().catch(()=>fail('Press Play to listen to this segment.'));};box.append(b);}lastReport={...r,input:inputMeta,filename:$('#clip-name').textContent,audienceGuess:guess,verifiedLabel:activeClip?.label??'unknown',source:activeClip?.source??'User-provided; origin unverified',createdAt:new Date().toISOString(),notice:'Research screening only. Frequency energy and window scores are supporting evidence, not proof. Verify through an official channel.'};return r;}
async function reveal(){if(!model||!wave||!guess||!played||busy)throw Error('Select audio, listen, and make a guess first.');const token=epoch;busy=true;ready();$('#error').hidden=true;text('#status','Analyzing locally…');const started=performance.now();return new Promise((resolve,reject)=>{worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});const thisWorker=worker;const done=()=>{clearTimeout(timer);thisWorker.terminate();if(worker===thisWorker)worker=null;if(token===epoch){busy=false;ready();}};const timer=setTimeout(()=>{done();const e=Error('Analysis took too long. Try a shorter recording.');if(token===epoch)fail(e.message);reject(e);},45000);thisWorker.onerror=()=>{done();const e=Error('Analysis could not start. Reload the page and try again.');if(token===epoch)fail(e.message);reject(e);};thisWorker.onmessage=e=>{done();if(token!==epoch){resolve(null);return;}if(e.data.error){fail(e.data.error);reject(Error(e.data.error));return;}const shown=showResult(e.data.result);text('#status',`Analyzed on this device in ${((performance.now()-started)/1000).toFixed(1)} s.`);resolve({label:shown.label,probability:shown.probability});};const copy=wave.slice();thisWorker.postMessage({id:token,wave:copy.buffer,model,sourceMode:mode},[copy.buffer]);});}
