$('#download-report').onclick=()=>{if(!lastReport)return;const url=URL.createObjectURL(new Blob([JSON.stringify(lastReport,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='govvoice-assessment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#known-error').onclick=async()=>{setMode('upload');const token=epoch;try{const meta=await fetch('failure.json');if(!meta.ok)throw Error('Error example unavailable.');const clip=await meta.json(),res=await fetch(clip.file);if(!res.ok)throw Error('Error example unavailable.');const blob=await res.blob();if(token!==epoch)return;await loadAudio(blob,'Known human false alarm',clip);$('#player').scrollIntoView({behavior:'smooth',block:'center'});}catch(e){if(token===epoch)fail(e.message);}};
function renderEvaluation(e){const c=e.conditions.clean;text('#eval-summary',`Trained on ${e.splits.train.n} clips; tuned on ${e.splits.tune.n}; calibrated on ${e.splits.calibration.n}. Primary locked test: ${c.n} paired human/synthetic recordings. ${e.protocol}`);const cards=[['Test accuracy',pct(c.accuracy),`95% interval ${pct(c.accuracy_ci95[0])}–${pct(c.accuracy_ci95[1])}`],['ROC-AUC',c.roc_auc.toFixed(3),'Ranking across decision thresholds'],['Decision coverage',pct(e.selective.coverage),`${e.selective.uncertain} clips returned uncertain`],['Accuracy when decided',pct(e.selective.accuracy),`${e.selective.accepted} accepted clips only`]];$('#metrics').replaceChildren(...cards.map(([label,value,note])=>{let d=document.createElement('div');d.className='metric';let a=document.createElement('span'),b=document.createElement('strong'),c=document.createElement('span');a.textContent=label;b.textContent=value;c.textContent=note;d.append(a,b,c);return d;}));$('#conditions').replaceChildren(...Object.entries(e.conditions).map(([k,m])=>{const tr=document.createElement('tr');for(const t of [({clean:'Clean',noise_20db:'Noise · 20 dB SNR',mp3_32kbps:'MP3 · 32 kbps'})[k],pct(m.accuracy),pct(m.precision),pct(m.recall),m.roc_auc.toFixed(3)]){const td=document.createElement('td');td.textContent=t;tr.append(td);}return tr;}));const cm=c.confusion_matrix;$('#matrix').replaceChildren(...[['Human → human',cm[0][0],false],['Human → synthetic',cm[0][1],true],['Synthetic → human',cm[1][0],true],['Synthetic → synthetic',cm[1][1],false]].map(([s,n,bad])=>{const d=document.createElement('div');if(bad)d.className='mistake';d.textContent=s;const v=document.createElement('strong');v.textContent=n;d.append(v);return d;}));text('#method-details',`${e.model}. Synthetic is the positive class. Table metrics force a 0.5 binary decision, including clips that the interface may mark uncertain. ${e.limitations.join(' ')}`);}
async function init(){try{const r=await fetch('model.json');if(!r.ok)throw Error('The trained detector is unavailable. Reload the page later.');model=await r.json();if(model.feature_version!=='mfcc90-v1'||model.mean.length!==90||model.scale.length!==90||!model.support.length||!Number.isFinite(model.calibration.slope))throw Error('The model file is invalid.');const neural=await fetch('neural-config.json');if(neural.ok)model.neural=await neural.json();ready();}catch(e){fail(e.message);return;}try{const r=await fetch('reel.json');if(!r.ok)throw Error('Demo reel unavailable. You can still upload audio.');reel=await r.json();$('#clip-select').replaceChildren(...reel.map((c,i)=>{const o=document.createElement('option');o.value=c.id;o.textContent='Sample '+String(i+1).padStart(2,'0');return o;}));if(mode==='reel')await chooseClip(reel[0].id);}catch(e){setMode('upload');fail(e.message);}try{const r=await fetch('evaluation.json');if(r.ok)renderEvaluation(await r.json());else text('#eval-summary','Evaluation details could not be loaded.');}catch{text('#eval-summary','Evaluation details could not be loaded.');}}
void init();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'govvoice_select_demo',description:'Select a blind listening sample. Does not play or reveal its assessment.',inputSchema:{type:'object',properties:{sample:{type:'integer',minimum:1,maximum:10}},required:['sample'],additionalProperties:false},execute:async input=>{if(!Number.isInteger(input.sample)||input.sample<1||input.sample>reel.length)throw Error('Invalid sample number.');if(mode!=='reel')setMode('reel');$('#clip-select').value=reel[input.sample-1].id;await chooseClip(reel[input.sample-1].id);if(!wave)throw Error('Audio could not be loaded.');return {sample:input.sample,ready:true};}},{name:'govvoice_read_assessment',description:'Read an already revealed assessment. Does not reveal hidden results.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>lastReport?{label:lastReport.label,probability:lastReport.probability,verifiedLabel:lastReport.verifiedLabel}:{revealed:false}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
window.addEventListener('pagehide',()=>{worker?.terminate();if(objectURL)URL.revokeObjectURL(objectURL);});

